SELECT 'users' AS source, COUNT(*) AS rows, md5(string_agg(concat_ws('|',COALESCE(CAST("uid" AS VARCHAR),'<NULL>'),COALESCE(CAST("user_name" AS VARCHAR),'<NULL>'),COALESCE(CAST("country_code" AS VARCHAR),'<NULL>'),COALESCE(CAST("base_fiat_currency" AS VARCHAR),'<NULL>'),COALESCE(CAST("kyc_level" AS VARCHAR),'<NULL>'),COALESCE(CAST("account_status" AS VARCHAR),'<NULL>'),COALESCE(CAST("created_at" AS VARCHAR),'<NULL>')),chr(10) ORDER BY "uid")) AS fingerprint FROM "sql_funds_flow"."main"."users" UNION ALL SELECT 'fiat_transactions' AS source, COUNT(*) AS rows, md5(string_agg(concat_ws('|',COALESCE(CAST("fiat_order_id" AS VARCHAR),'<NULL>'),COALESCE(CAST("uid" AS VARCHAR),'<NULL>'),COALESCE(CAST("direction" AS VARCHAR),'<NULL>'),COALESCE(CAST("currency" AS VARCHAR),'<NULL>'),COALESCE(CAST("amount" AS VARCHAR),'<NULL>'),COALESCE(CAST("fee" AS VARCHAR),'<NULL>'),COALESCE(CAST("channel" AS VARCHAR),'<NULL>'),COALESCE(CAST("status" AS VARCHAR),'<NULL>'),COALESCE(CAST("created_at" AS VARCHAR),'<NULL>'),COALESCE(CAST("completed_at" AS VARCHAR),'<NULL>')),chr(10) ORDER BY "fiat_order_id")) AS fingerprint FROM "sql_funds_flow"."main"."fiat_transactions" UNION ALL SELECT 'crypto_transactions' AS source, COUNT(*) AS rows, md5(string_agg(concat_ws('|',COALESCE(CAST("crypto_order_id" AS VARCHAR),'<NULL>'),COALESCE(CAST("uid" AS VARCHAR),'<NULL>'),COALESCE(CAST("direction" AS VARCHAR),'<NULL>'),COALESCE(CAST("asset" AS VARCHAR),'<NULL>'),COALESCE(CAST("network" AS VARCHAR),'<NULL>'),COALESCE(CAST("amount" AS VARCHAR),'<NULL>'),COALESCE(CAST("fee" AS VARCHAR),'<NULL>'),COALESCE(CAST("tx_hash" AS VARCHAR),'<NULL>'),COALESCE(CAST("address" AS VARCHAR),'<NULL>'),COALESCE(CAST("status" AS VARCHAR),'<NULL>'),COALESCE(CAST("confirmations" AS VARCHAR),'<NULL>'),COALESCE(CAST("created_at" AS VARCHAR),'<NULL>'),COALESCE(CAST("completed_at" AS VARCHAR),'<NULL>')),chr(10) ORDER BY "crypto_order_id")) AS fingerprint FROM "sql_funds_flow"."main"."crypto_transactions" UNION ALL SELECT 'exchange_rates' AS source, COUNT(*) AS rows, md5(string_agg(concat_ws('|',COALESCE(CAST("asset" AS VARCHAR),'<NULL>'),COALESCE(CAST("asset_name" AS VARCHAR),'<NULL>'),COALESCE(CAST("asset_type" AS VARCHAR),'<NULL>'),COALESCE(CAST("quote_currency" AS VARCHAR),'<NULL>'),COALESCE(CAST("rate_to_usdt" AS VARCHAR),'<NULL>'),COALESCE(CAST("usdt_to_asset_rate" AS VARCHAR),'<NULL>'),COALESCE(CAST("effective_date" AS VARCHAR),'<NULL>'),COALESCE(CAST("source" AS VARCHAR),'<NULL>')),chr(10) ORDER BY "asset")) AS fingerprint FROM "sql_funds_flow"."main"."exchange_rates" ORDER BY source;